切り上げ・切り捨て・四捨五入を行う例<pre><code>#include &lt;stdio.h&gt;
#include &lt;math.h&gt;

int main()
{
	double x;
	scanf("%lf", &amp;x);
	printf("ceil: %f\n", ceil(x));
	printf("floor: %f\n", floor(x));
	printf("round: %f\n", round(x));
}
</code></pre>

最小値・最大値を求める例<pre><code>#include &lt;stdio.h&gt;
#include &lt;math.h&gt;

int main()
{
	printf("%f\n", fmin(3.14, 2.71));
	printf("%f\n", fmin(-1.0, 1.0));

	printf("%f\n", fmax(3.14, 2.71));
	printf("%f\n", fmax(-1.0, 1.0));
}
</code></pre>

対数・指数を求める例<pre><code>#include &lt;stdio.h&gt;
#include &lt;math.h&gt;

int main()
{
	printf("%f\n", log(2.718281828459045));
	printf("%f\n", log2(8.0));
	printf("%f\n", log10(1000.0));

	printf("%f\n", exp(1.0));
	printf("%f\n", exp(2.0));
}
</code></pre>

斜辺の長さを求める例<pre><code>#include &lt;stdio.h&gt;
#include &lt;math.h&gt;

int main()
{
	double x, y;
	scanf("%lf %lf", &amp;x, &amp;y);
	printf("%f\n", hypot(x, y));
}
</code></pre> 斜辺の長さを自力で計算する例<pre><code>#include &lt;stdio.h&gt;
#include &lt;math.h&gt;

int main()
{
	double x, y;
	scanf("%lf %lf", &amp;x, &amp;y);
	printf("%f\n", sqrt(x * x + y * y));
}
</code></pre>

三角関数を求める例<pre><code>#include &lt;stdio.h&gt;
#include &lt;math.h&gt;

int main()
{
	double pi = 3.141592653589793;
	double angle;
	scanf("%lf", &amp;angle);

	printf("sin: %f\n", sin(angle * pi / 180.0));
	printf("cos: %f\n", cos(angle * pi / 180.0));
	printf("tan: %f\n", tan(angle * pi / 180.0));
}
</code></pre>

戻り値を変数に代入する例<pre><code>#include &lt;stdio.h&gt;
#include &lt;math.h&gt;

int main()
{
	double result = sqrt(16.0);
	printf("%f\n", result);
}
</code></pre> 戻り値を別の関数の引数にする例<pre><code>#include &lt;stdio.h&gt;
#include &lt;math.h&gt;

int main()
{
	double a = 0.3, b = 0.2, c = 0.4;
	double min = fmin(fmin(a, b), c);
	printf("%f\n", min);
}
</code></pre> 戻り値を演算や条件式で使う例<pre><code>#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

int main()
{
	int x;
	scanf("%d", &amp;x);

	if (10 &lt; abs(x))
	{
		puts("絶対値が 10 より大きい");
	}
	else
	{
		puts("絶対値が 10 以下");
	}
}
</code></pre> 戻り値を使わない例<pre><code>#include &lt;stdio.h&gt;

int main()
{
	printf("Apple\n"); // 戻り値を使わない例

	// 戻り値を使う例
	int result = printf("Banana\n");
	printf("%d\n", result);
}
</code></pre> 戻り値を無視する例<pre><code>#include &lt;stdio.h&gt;
#include &lt;math.h&gt;

int main()
{
	sqrt(16.0);
}
</code></pre>

引数の暗黙的な型変換の例<pre><code>#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;math.h&gt;

int main()
{
	printf("%f\n", sqrt(25)); // int → double
	printf("%d\n", abs(true)); // bool → int
	printf("%lld\n", llabs(-100)); // int → long long
}
</code></pre>

関数定義の例<pre><code>#include &lt;stdio.h&gt;

int Square(int n)
{
	return n * n;
}

int main()
{
	printf("%d\n", Square(5));
}
</code></pre> 関数宣言を使った関数定義の例<pre><code>#include &lt;stdio.h&gt;

int Square(int n); // 関数宣言

int main()
{
	printf("%d\n", Square(5));
}

int Square(int n) // 関数定義
{
	return n * n;
}
</code></pre> 誤り: 関数宣言や定義の前で関数を呼んでいる<pre><code>#include &lt;stdio.h&gt;

int main()
{
	// 誤り：関数宣言より前で呼び出している
	printf("%d\n", Square(5));
}

int Square(int n);

int Square(int n)
{
	return n * n;
}
</code></pre>

仮引数と実引数の例<pre><code>#include &lt;stdio.h&gt;

int Square(int n); // n は仮引数

int main()
{
	int result = Square(5); // 5 は実引数
	printf("%d\n", result); // "%d\n" と result は printf の実引数
}

int Square(int n) // n は仮引数
{
	return n * n;
}
</code></pre>

return 文の挙動を確認するコード<pre><code>#include &lt;stdio.h&gt;

int Square(int n)
{
	puts("A");
	return n * n;
	puts("B"); // ここは実行されない
}

int main()
{
	int result = Square(5);
	printf("%d\n", result);
}
</code></pre> ❌ 誤り: 戻り値の型に合わない値をreturn している<pre><code>#include &lt;stdio.h&gt;

int Half(int n) // 戻り値の型は int
{
	return n / 2.0; // 計算結果は double 型だが、int に変換されて返される
}

int main()
{
	printf("%d\n", Half(5));
}
</code></pre> ❌ 誤り: return 文が実行されない場合がある<pre><code>#include &lt;stdio.h&gt;

int Max(int a, int b)
{
	if (a &gt; b)
	{
		return a;
	}

	if (a &lt; b)
	{
		return b;
	}

	// ❌️ a == b の場合に return 文が実行されない
}

int main()
{
	printf("%d\n", Max(3, 3));
}
</code></pre> ⭕️ 必ず return 文が実行される<pre><code>#include &lt;stdio.h&gt;

int Max(int a, int b)
{
	if (a &gt; b)
	{
		return a;
	}
	else
	{
		return b;
	}
}

int main()
{
	printf("%d\n", Max(3, 3));
}
</code></pre>

戻り値のない関数の例<pre><code>#include &lt;stdio.h&gt;

void PrintNumber(int n)
{
	printf("%d\n", n);
}

void PrintHello()
{
	puts("Hello!");
}

void DrawLine(int length)
{
	for (int i = 0; i &lt; length; ++i)
	{
		putchar('-');
	}

	putchar('\n');
}

int main()
{
	PrintNumber(123);
	PrintHello();
	DrawLine(10);
}
</code></pre>

戻り値のない関数での return 文の例<pre><code>#include &lt;stdio.h&gt;

void DrawLine(int length)
{
	if (length &lt;= 0) // 長さが 0 以下の場合は何もせず終了
	{
		return;
	}

	if (100 &lt; length) // 長さが大きすぎる場合は何もせず終了
	{
		return;
	}

	for (int i = 0; i &lt; length; ++i)
	{
		putchar('-');
	}

	putchar('\n');
}

int main()
{
	DrawLine(0); // 何も出力されない
	DrawLine(200); // 何も出力されない
	DrawLine(10);
}
</code></pre>

関数本体の変数のスコープ<pre><code>#include &lt;stdio.h&gt;

int Square(int n) // 仮引数 n のスコープはこの関数本体内
{
	int result = n * n; // result のスコープはこの関数本体内
	return result;
}

int main()
{
	int n = 2; // Square 関数の仮引数 n とは無関係
	printf("%d\n", Square(n + 3));

	// ❌️Square 関数内の result は main 関数内では使えない
	// printf("%d\n", result);
}
</code></pre> 関数内の変数の挙動を確認するコード<pre><code>#include &lt;stdio.h&gt;

int Counter()
{
	int count = 0; // count は毎回新しく作られる
	++count;
	return count;
}

int main()
{
	printf("%d\n", Counter());
	printf("%d\n", Counter());
	printf("%d\n", Counter());
}
</code></pre>

円の面積を出力する関数の例<pre><code>#include &lt;stdio.h&gt;

void GetCircleArea(double radius)
{
	double pi = 3.141592653589793;
	double area = pi * radius * radius;
	printf("円の面積: %f\n", area);
}

int main()
{
	GetCircleArea(5.0);
}
</code></pre> 円の面積を返す関数の例<pre><code>#include &lt;stdio.h&gt;

double GetCircleArea(double radius)
{
	double pi = 3.141592653589793;
	return pi * radius * radius;
}

int main()
{
	double area1 = GetCircleArea(5.0);
	double area2 = GetCircleArea(10.0);
	printf("面積の和: %f\n", (area1 + area2));
}
</code></pre>

偶数であるかを判定する関数<pre><code>#include &lt;stdio.h&gt;

bool IsEven(int n)
{
	return (n % 2) == 0;
}

int main()
{
	int x;
	scanf("%d", &amp;x);

	if (IsEven(x))
	{
		puts("偶数");
	}
	else
	{
		puts("奇数");
	}
}
</code></pre>

奇数であるかを判定する関数<pre><code>#include &lt;stdio.h&gt;

bool IsOdd(int n)
{
	return (n % 2) != 0;
}

int main()
{
	int x;
	scanf("%d", &amp;x);

	if (IsOdd(x))
	{
		puts("奇数");
	}
	else
	{
		puts("偶数");
	}
}
</code></pre>

指定した幅・高さ・文字で長方形を描く関数<pre><code>#include &lt;stdio.h&gt;

void DrawRectangle(int width, int height, char c)
{
	for (int y = 0; y &lt; height; ++y)
	{
		for (int x = 0; x &lt; width; ++x)
		{
			putchar(c);
		}

		putchar('\n');
	}
}

int main()
{
	DrawRectangle(4, 3, '#');
	DrawRectangle(6, 6, '*');
}
</code></pre>

2 つの整数のうち大きい方を返す関数<pre><code>#include &lt;stdio.h&gt;

int Max(int a, int b)
{
	if (a &gt; b)
	{
		return a;
	}
	else
	{
		return b;
	}
}

int main()
{
	int x, y;
	scanf("%d %d", &amp;x, &amp;y);
	printf("%d\n", Max(x, y));
}
</code></pre> 条件演算子を使った Max 関数の例<pre><code>#include &lt;stdio.h&gt;

int Max(int a, int b)
{
	return (a &gt; b) ? a : b;
}

int main()
{
	int x, y;
	scanf("%d %d", &amp;x, &amp;y);
	printf("%d\n", Max(x, y));
}
</code></pre>

3 つの整数のうち最大値を返す関数<pre><code>#include &lt;stdio.h&gt;

int Max3(int a, int b, int c)
{
	int max = a;

	if (max &lt; b)
	{
		max = b;
	}

	if (max &lt; c)
	{
		max = c;
	}

	return max;
}

int main()
{
	int x, y, z;
	scanf("%d %d %d", &amp;x, &amp;y, &amp;z);
	printf("%d\n", Max3(x, y, z));
}
</code></pre> Max 関数を使った Max3 関数の例<pre><code>#include &lt;stdio.h&gt;

int Max(int a, int b)
{
	return (a &gt; b) ? a : b;
}

int Max3(int a, int b, int c)
{
	return Max(Max(a, b), c);
}

int main()
{
	int x, y, z;
	scanf("%d %d %d", &amp;x, &amp;y, &amp;z);
	printf("%d\n", Max3(x, y, z));
}
</code></pre>

2 点間の距離を求める関数<pre><code>#include &lt;stdio.h&gt;
#include &lt;math.h&gt;

double Distance(double x1, double y1, double x2, double y2)
{
	return hypot((x2 - x1), (y2 - y1));
}

int main()
{
	double x1, y1, x2, y2;
	scanf("%lf %lf %lf %lf", &amp;x1, &amp;y1, &amp;x2, &amp;y2);
	printf("%f\n", Distance(x1, y1, x2, y2));
}
</code></pre>

素数判定を行う関数<pre><code>#include &lt;stdio.h&gt;

bool IsPrime(int n)
{
	if (n &lt;= 1)
	{
		return false;
	}

	for (int i = 2; i &lt;= (n / 2); ++i)
	{
		if ((n % i) == 0) // 割り切れた場合
		{
			return false;
		}
	}

	return true;
}

int main()
{
	int x;
	scanf("%d", &amp;x);

	if (IsPrime(x))
	{
		puts("素数");
	}
	else
	{
		puts("素数ではない");
	}
}
</code></pre>

❌ const を使わない場合に起こる問題の例<pre><code>#include &lt;stdio.h&gt;

int main()
{
	double pi = 3.1415926535; // 円周率
	pi = pi * 2.0; // ミス: 円周率の値を上書きしてしまった
	printf("円周率: %f\n", pi);
}
</code></pre>

⚠️ const を付けた変数の値の変更<pre><code>#include &lt;stdio.h&gt;

int main()
{
	const double pi = 3.1415926535; // 円周率（読み取り専用）
	pi = pi * 2.0; // コンパイルエラー: const 変数に代入しようとした
	printf("円周率: %f\n", pi);
}
</code></pre> ❌ 誤り: const 変数に初期値を与えていない<pre><code>#include &lt;stdio.h&gt;

int main()
{
	const int maxUser;
	maxUser = 100; // コンパイルエラー
	printf("最大ユーザー数: %d\n", maxUser);
}
</code></pre> ❌ 誤り: const 変数の値を変更しようとしている<pre><code>#include &lt;stdio.h&gt;

int main()
{
	const int maxUser = 100;
	maxUser = 200; // コンパイルエラー
