モンテカルロ法による円周率の近似<pre><code>#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;time.h&gt;

// [0.0, 1.0] の範囲の乱数を返す関数
double RandomDouble()
{
	return (double)rand() / RAND_MAX;
}

int main()
{
	srand((unsigned int)time(NULL));

	printf("試行回数を入力してください &gt; ");
	int n;
	scanf("%d", &amp;n);

	// 扇形の内側に入った点の個数
	int insideSector = 0;

	for (int i = 0; i &lt; n; ++i)
	{
		const double x = RandomDouble(); // x 座標
		const double y = RandomDouble(); // y 座標

		// 原点からの距離の 2 乗が 1.0 以下なら扇形の内側
		if ((x * x + y * y) &lt;= 1.0)
		{
			++insideSector;
		}
	}

	const double result = (double)insideSector / n * 4.0;
	printf("近似された円周率: %f\n", result);
}
</code></pre>

