関数ポインタを返す関数の例（演算子に応じた関数を選択して計算する関数）<pre><code>#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;

double Add(double x, double y)
{
	return (x + y);
}

double Sub(double x, double y)
{
	return (x - y);
}

double Mul(double x, double y)
{
	return (x * y);
}

double Div(double x, double y)
{
	return (x / y);
}

// 戻り値が double で引数が (double, double) の関数のアドレスを返す関数
// 関数名は GetFunction であり、GetFunction 関数自体の引数は (char op)
double (*GetFunction(char op))(double, double)
{
	switch (op)
	{
	case '+':
		return Add;
	case '-':
		return Sub;
	case '*':
		return Mul;
	case '/':
		return Div;
	default:
		puts("不明な演算子");
		exit(EXIT_FAILURE);
	}
}

// x と y に対して、演算子 op に応じた計算を行う関数
double Evaluate(double x, char op, double y)
{
	// 取得した関数ポインタ経由で関数を呼び出す
	return GetFunction(op)(x, y);
}

int main()
{
	printf("%f\n", Evaluate(2.5, '+', 1.2));
	printf("%f\n", Evaluate(2.5, '-', 1.2));
	printf("%f\n", Evaluate(2.5, '*', 1.2));
	printf("%f\n", Evaluate(2.5, '/', 1.2));
}
</code></pre>

