	const int a = *(const int*)p1;
	const int b = *(const int*)p2;

	if (a &lt; b)
	{
		return -1;
	}
	else if (a &gt; b)
	{
		return 1;
	}
	else
	{
		return 0;
	}
}

int main()
{
	int x = 10;
	int y = 20;
	printf("比較結果: %d\n", CompareInt(&amp;x, &amp;y));
}
