qsort を使った構造体配列のソート例<pre><code>#include &lt;stdio.h&gt;
#include &lt;stdlib.h&gt;
#include &lt;math.h&gt;
#define COUNTOF(arr) ((int)(sizeof(arr)/sizeof((arr)[0])))

typedef struct
{
	double x;
	double y;
} Vec2;

// Vec2 の原点からの距離を比較する関数
int CompareVec2(const void* p1, const void* p2)
{
	const Vec2* v1 = (const Vec2*)p1;
	const Vec2* v2 = (const Vec2*)p2;
	const double len1 = hypot(v1-&gt;x, v1-&gt;y);
	const double len2 = hypot(v2-&gt;x, v2-&gt;y);
	return (len1 &gt; len2) - (len1 &lt; len2);
}

int main()
{
	Vec2 vectors[] =
	{
		{ 3.0, 4.0 },
		{ 1.0, 1.0 },
		{ -1.0, 5.0 },
		{ 2.0, 2.0 }
	};

	qsort(vectors, COUNTOF(vectors), sizeof(Vec2), CompareVec2);

	// ソート結果の出力
	for (int i = 0; i &lt; COUNTOF(vectors); ++i)
	{
		printf("(%.2f, %.2f)\n", vectors[i].x, vectors[i].y);
	}
}
