ブレゼンハムのアルゴリズム<pre><code>// 省略: 21.2.1 画像プログラミングの共通コード

// 線分を描く関数
void DrawLine(Image* image, int x0, int y0, int x1, int y1, RGB color)
{
	const int dx = abs(x1 - x0);
	const int dy = abs(y1 - y0);
	const int sx = (x0 &lt; x1) ? 1 : -1;
	const int sy = (y0 &lt; y1) ? 1 : -1;
	int x = x0;
	int y = y0;
	int error = (dx - dy);

	for (;;)
	{
		SetPixel(image, x, y, color);

		if ((x == x1) &amp;&amp; (y == y1))
		{
			break;
		}

		const int e2 = (error * 2);

		if (e2 &gt; -dy)
		{
			error -= dy;
			x += sx;
		}

		if (e2 &lt; dx)
		{
			error += dx;
			y += sy;
		}
	}
}

int main()
{
	Image* image = CreateImage(256, 256);
	DrawLine(image, 50, 50, 200, 150, (RGB){ 0.0, 0.0, 0.0 });
	Save("bresenham.bmp", image);
	DestroyImage(image);
}
