		for (int x = -offset; x &lt; image-&gt;width; x += brickWidth)
		{
			const int tone = (row * 3 + x / brickWidth * 5) % 4;

			// レンガの色を少しずつ変える（tone の値によって 4 種類の色を使い分ける）
